INSERT INTO transcript (conversation_id, item_id, seq, role, text, complete, at, copied_at, compaction) VALUES (1, 'toolu_013PfWtQSjFgK44vHf6Ltu1X', 18, 'tool', '1	# Legislația despre burnout la locul de muncă (România)
2	
3	## Ce spune legea azi
4	
5	Burnout-ul nu este recunoscut în România ca boală profesională de sine
6	stătătoare. Codul Muncii obligă angajatorul să asigure securitatea și
7	sănătatea lucrătorilor în toate aspectele legate de muncă (art. 175), iar
8	Legea 319/2006 a securității și sănătății în muncă cere evaluarea riscurilor,
9	inclusiv a celor psihosociale.
10	
11	## Obligațiile angajatorului
12	
13	<!-- de completat: evaluarea riscurilor psihosociale, medicina muncii,
14	     informarea și consultarea lucrătorilor; cu trimiteri la articole -->
15	
16	## Drepturile angajatului
17	
18	<!-- de completat: concediul medical, adaptarea postului, dreptul de a
19	     refuza munca în condiții de pericol -->
20	
21	## Ce se schimbă la nivel european
22	
23	Din 2022 Organizația Mondială a Sănătății descrie burnout-ul în ICD-11 ca un
24	fenomen ocupațional, nu ca o boală. Comisia Europeană a anunțat în 2023 o
25	inițiativă privind riscurile psihosociale la locul de muncă.
26	
27	<!-- de completat: unde stă inițiativa azi, ce înseamnă pentru angajatorii
28	     din România -->
29	', 1, '2026-10-31T16:04:56.006Z', '2026-10-31T16:04:56.639Z', 0);
