INSERT INTO transcript (conversation_id, item_id, seq, role, text, complete, at, copied_at, compaction) VALUES (1, 'toolu_018ZNSB2rtrN9ftL3d1Q1L33', 42, 'tool', '1	<!doctype html>
2	<html lang="ro">
3	<head>
4	  <meta charset="utf-8">
5	  <title>Despre noi — Burnout la locul de muncă</title>
6	  <link rel="stylesheet" href="style.css">
7	</head>
8	<body>
9	  <header>
10	    <h1>Despre noi</h1>
11	    <nav><a href="index.html">Acasă</a> · <a href="despre.html">Despre noi</a> · <a href="evaluare.html">Evaluare</a> · <a href="en/about.html">EN</a></nav>
12	  </header>
13	  <main>
14	    <p>Un program de prevenire a burnout-ului care ajută echipele și managerii să identifice și să abordeze riscul de epuizare profesională.</p>
15	
16	    <section class="cards">
17	      <article>
18	        <h2>Ce măsurăm</h2>
19	        <p>Programa evaluează trei dimensiuni ale burnout-ului: epuizare fizică și emoțională, cinism și detașare de muncă, și scăderea eficienței profesionale. Fiecare dimensiune contribuie la un scor de risc general.</p>
20	      </article>
21	      <article>
22	        <h2>Cum funcționează</h2>
23	        <p>Echipele completează un chestionar anonim de 20 de minute. Rezultatele sunt prezentate echipei și managerului cu un scor pe culori (verde, galben, portocaliu, roșu) și o valoare între 0 și 100, fără a expune răspunsurile individuale.</p>
24	      </article>
25	      <article>
26	        <h2>Confidențialitate și anonimitate</h2>
27	        <p>Răspunsurile individuale rămân anonime. Doar scorul pe echipă este vizibil pentru manageri și HR. Niciun răspuns personal nu este dezvăluit, garantând încrederea și siguranța participanților.</p>
28	      </article>
29	      <article>
30	        <h2>După evaluare</h2>
31	        <p>Rezultatele sunt discutate cu echipa în termen de o săptămână. Managerul primește recomandări specifice pentru patru săptămâni, axate pe reducerea factorilor de risc și îmbunătățirea bien-stării echipei.</p>
32	      </article>
33	      <article>
34	        <h2>Pentru cine</h2>
35	        <p>Programul este conceput pentru organizații care doresc să prevină burnout-ul, să mențină angajații sănătoși și productivi, și să creeze un mediu de muncă mai sustenabil.</p>
36	      </article>
37	      <article>
38	        <h2>De ce contează</h2>
39	        <p>Burnout-ul afectează performanța, sănătatea și retenția angajaților. O evaluare proactivă permite intervenție timpurie și prevenție, mai degrabă decât gestionarea consecințelor.</p>
40	      </article>
41	    </section>
42	  </main>
43	  <footer>
44	    <nav>
45	      <a href="despre.html">Despre noi</a> · <a href="faq.html">FAQ</a> · <a href="contact.html">Contact</a>
46	    </nav>
47	  </footer>
48	</body>
49	</html>
50	', 1, '2026-10-31T16:06:26.136Z', '2026-10-31T16:06:27.653Z', 0);
