INSERT INTO transcript (conversation_id, item_id, seq, role, text, complete, at, copied_at, compaction) VALUES (1, 'toolu_0181CttPbCP8NfpFfPTGp8M4', 44, 'tool', '1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <title>About us — Burnout at Work</title>
6	  <link rel="stylesheet" href="../style.css">
7	</head>
8	<body>
9	  <header>
10	    <h1>About us</h1>
11	    <nav><a href="index.html">Home</a> · <a href="about.html">About us</a> · <a href="assessment.html">Assessment</a> · <a href="../index.html">RO</a></nav>
12	  </header>
13	  <main>
14	    <p>A burnout prevention programme that helps teams and managers identify and address the risk of professional exhaustion.</p>
15	
16	    <section class="cards">
17	      <article>
18	        <h2>What we measure</h2>
19	        <p>The programme assesses three dimensions of burnout: physical and emotional exhaustion, cynicism and detachment from work, and reduced professional efficacy. Each dimension contributes to an overall risk score.</p>
20	      </article>
21	      <article>
22	        <h2>How it works</h2>
23	        <p>Teams complete an anonymous 20-minute questionnaire. Results are presented to the team and manager with a colour-coded score (green, yellow, orange, red) and a value between 0 and 100, without exposing individual responses.</p>
24	      </article>
25	      <article>
26	        <h2>Confidentiality and anonymity</h2>
27	        <p>Individual responses remain anonymous. Only the team score is visible to managers and HR. No personal answers are disclosed, ensuring trust and participant safety.</p>
28	      </article>
29	      <article>
30	        <h2>After assessment</h2>
31	        <p>Results are discussed with the team within one week. The manager receives specific recommendations for four weeks, focused on reducing risk factors and improving team wellbeing.</p>
32	      </article>
33	      <article>
34	        <h2>Who it''s for</h2>
35	        <p>The programme is designed for organisations that want to prevent burnout, keep employees healthy and productive, and create a more sustainable work environment.</p>
36	      </article>
37	      <article>
38	        <h2>Why it matters</h2>
39	        <p>Burnout affects performance, health and employee retention. Proactive assessment enables early intervention and prevention, rather than managing the consequences.</p>
40	      </article>
41	    </section>
42	  </main>
43	  <footer>
44	    <nav>
45	      <a href="about.html">About us</a> · <a href="faq.html">FAQ</a> · <a href="contact.html">Contact</a>
46	    </nav>
47	  </footer>
48	</body>
49	</html>
50	', 1, '2026-10-31T16:06:27.764Z', '2026-10-31T16:06:27.975Z', 0);
